import XCTest
import CoreGraphics
@testable import Mango
@testable import Port

/// Pixel-exact layout regression tests.
///
/// Every expected value below was produced by compiling mango's own C layout functions
/// (horizontal.c, vertical.c, scroll.c, dwindle.c, overview.c: the function bodies, extracted
/// verbatim, behind stubs for the client list and `client_tile_resize`) and running them on the
/// scenarios described in the helpers, with `-ffp-contract=off` (no fused multiply-add, like an
/// x86-64 build). They pin the integer/float semantics of the C code: `mfact`, per-client shares,
/// scroller proportions and dwindle ratios are `float`, so for example 2560 wide with
/// `default_master_factor=0.9` gives a 2303 px master (not 2304) because 0.9f is 0.89999998.
final class LayoutGoldenTests: MangoTestCase {

    // MARK: Parameter sets (index = the number in the vectors)

    struct Params { var x, y, w, h, ih, iv, oh, ov, nmaster: Int; var mfact: Double; var overspread, single: Bool }

    static let params: [Params] = [
        Params(x: 0, y: 25, w: 1920, h: 1080, ih: 5, iv: 5, oh: 10, ov: 10, nmaster: 1, mfact: 0.55, overspread: false, single: true),
        Params(x: -1920, y: -200, w: 1920, h: 1080, ih: 15, iv: 15, oh: 12, ov: 12, nmaster: 2, mfact: 0.62, overspread: false, single: true),
        Params(x: 0, y: 0, w: 2560, h: 1440, ih: 0, iv: 0, oh: 0, ov: 0, nmaster: 3, mfact: 0.9, overspread: true, single: true),
        Params(x: 100, y: 30, w: 1437, h: 899, ih: 7, iv: 3, oh: 11, ov: 13, nmaster: 0, mfact: 0.3, overspread: false, single: false),
        Params(x: 0, y: 38, w: 1000, h: 700, ih: 10, iv: 10, oh: 10, ov: 10, nmaster: 1, mfact: 0.7, overspread: false, single: true),
        Params(x: 0, y: 0, w: 1710, h: 1073, ih: 6, iv: 8, oh: 9, ov: 4, nmaster: 2, mfact: 0.5, overspread: true, single: false),
    ]

    static func rects(_ tokens: [Substring]) -> [CGRect] {
        tokens.map { tok in
            let v = tok.split(separator: ",").map { Double($0)! }
            return CGRect(x: v[0], y: v[1], width: v[2], height: v[3])
        }
    }

